      "ar": "قَالُواْ أَتَعْجَبِينَ مِنْ أَمْرِ اللَّهِ رَحْمَتُ اللَّهِ وَبَرَكَٰتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ إِنَّهُ حَمِيدٌ مَّجِيدٌ",
      "translit": "Qālū ataʿjabīna min amri llāhi raḥmatu llāhi wabarakātuhū ʿalaykum ahla l-bayti innahū ḥamīdun majīd",
