      "ar": "فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ الرَّوْعُ وَجَاءَتْهُ الْبُشْرَىٰ يُجَٰدِلُنَا فِي قَوْمِ لُوطٍ",
